import os
import subprocess

def compress_directory(directory_path, output_archive_name):
    try:
        command = f""7z a {output_archive_name} {directory_path}\\*""
        process = subprocess.run(command, shell=True, stdout=subprocess.PIPE, stderr=subprocess.PIPE)
        if process.returncode == 0:
            return 0
        else:
            return 1
    except Exception as e:
        print(f""Error: {e}"")
        return 1

if __name__ == ""__main__"":
    import sys
    if len(sys.argv) != 3:
        print(""Usage: python script_name.py <directory_path> <output_archive_name>"")
        sys.exit(1)

    directory_path = sys.argv[1]
    output_archive_name = sys.argv[2]

    status_code = compress_directory(directory_path, output_archive_name)

    if status_code == 0:
        print(f""Archive {output_archive_name} created successfully"")
    else:
        print(""Error occurred while creating the archive"")']",63,[1],['CWE-78'],True,0,0,0,

