        c.execute(""INSERT INTO {} VALUES ({})"".format(table_name, "","".join([""?""] * len(fields))), tuple(record.values()))
        conn.commit()

    c.execute(""SELECT * FROM {}"".format(table_name))
    records = c.fetchall()
    print(""Generated and inserted {} records into table {}"".format(num_records, table_name))

    for record in records:
        if not validate_record(record):
            print(""Error: Record does not meet validation criteria"")
            return False
    return True

