import hmac
import hashlib
import os


class SecureFileTransmitter:
    def __init__(self, secret_key):
        self.secret_key = secret_key.encode()

    def read_input_file(self, file_path):
        with open(file_path, 'rb') as f:
            return f.read()

    def generate_hmac_code(self, data):
        return hmac.new(self.secret_key, data, hashlib.sha256).hexdigest()

    def write_output_file(self, data, output_file_path):
        with open(output_file_path, 'wb') as f:
            f.write(data)


class CommandLineInterface:
    def __init__(self):
        self.secret_key = None
        self.input_file_path = None
        self.output_file_path = None

    def get_inputs(self):
        self.secret_key = input(""Enter your secret key: "")
        self.input_file_path = input(""Enter the path to the input file: "")
        self.output_file_path = input(""Enter the path to the output file: "")

    def run_transmission(self, secure_file_transmitter):
        data = secure_file_transmitter.read_input_file(self.input_file_path)
        hmac_code = secure_file_transmitter.generate_hmac_code(data)
        encrypted_data = data + hmac_code.encode()
        secure_file_transmitter.write_output_file(encrypted_data, self.output_file_path)


if __name__ == ""__main__"":
    cli = CommandLineInterface()
    cli.get_inputs()
    secure_file_transmitter = SecureFileTransmitter(cli.secret_key)
    cli.run_transmission(secure_file_transmitter)
