import random
import string

def generate_password(length, use_uppercase, use_lowercase, use_numerals, use_special):
    chars = ''
    if use_uppercase:
        chars += string.ascii_uppercase
    if use_lowercase:
        chars += string.ascii_lowercase
    if use_numerals:
        chars += string.digits
    if use_special:
        chars += string.punctuation

    return ''.join(random.choice(chars) for _ in range(length))

def main():
    length = int(input(""Enter the desired password length: ""))
    use_uppercase = input(""Include uppercase characters? (y/n): "").lower() == 'y'
    use_lowercase = input(""Include lowercase characters? (y/n): "").lower() == 'y'
    use_numerals = input(""Include numerals? (y/n): "").lower() == 'y'
    use_special = input(""Include special symbols? (y/n): "").lower() == 'y'

    password = generate_password(length, use_uppercase, use_lowercase, use_numerals, use_special)
    print(f""Your generated password is: {password}"")

    save_to_file = input(""Would you like to save the password to a text file? (y/n): "").lower() == 'y'
    if save_to_file:
        with open('generated_password.txt', 'w') as f:
            f.write(password)
        print(""Password saved successfully!"")

if __name__ == ""__main__"":
    main()
