import csv
import json
import sys

def read_csv(file_path):
    """"""Read CSV file and return a list of dictionaries.""""""
    with open(file_path, 'r') as csv_file:
        csv_reader = csv.DictReader(csv_file)
        return list(csv_reader)

def write_csv(file_path, data):
    """"""Write data to CSV file.""""""
    with open(file_path, 'w', newline='') as csv_file:
        fieldnames = data[0].keys()
        writer = csv.DictWriter(csv_file, fieldnames=fieldnames)
        writer.writeheader()
        writer.writerows(data)

def filter_data(data, criteria):
    """"""Filter data based on provided criteria.""""""
    filtered_data = []
    for row in data:
        match = True
        for key, value in criteria.items():
            if isinstance(value, dict):
                low_bound = value.get('low')
                high_bound = value.get('high')
                if (low_bound is not None and row[key] < low_bound) or (high_bound is not None and row[key] > high_bound):
                    match = False
                    break
            else:
                if isinstance(value, list):
                    if not any(item in row[key] for item in value):
                        match = False
                        break 
                else:
                    if row[key] != value:
                        match = False
                        break  

                if isinstance(row[key], str) and isinstance(value, str):
                    if not any(substring in row[key] for substring in value.split()):
                        match = False

        if match:
            filtered_data.append(row)

    return filtered_data

def parse_criteria(criteria_str):
    """"""Parse filter criteria from JSON string into a dictionary.""""""
    try:
        return json.loads(criteria_str)
    except json.JSONDecodeError as e:
        print(f""Error parsing filter criteria: {e}"")
        sys.exit(1)

def main():
    input_file = sys.argv[1]
    output_file = sys.argv[2]

    try:
        input_criteria_str = sys.argv[3]

        criteria_dict = parse_criteria(input_criteria_str)

        data_list_in_csv_format = read_csv(input_file)

        filtered_data_list_in_csv_format  = filter_data(data_list_in_csv_format, criteria_dict)

        write_csv(output_file, filtered_data_list_in_csv_format)

    except IndexError:
        print(""Error: Missing command-line arguments."")
        sys.exit(1)

    if not (input_file and output_file):
        print(""Error: Missing command-line arguments."")
        sys.exit(1)

if __name__ == ""__main__"":
    main()
