Finally, design a main function that demonstrates how these functions can be used in practice by calculating and verifying both MD5 and SHA-256 hashes for one or more files provided as input arguments.",['CWE-328'],,"['```
import hashlib
import os


def calculate_sha256(file_path, chunk_size):
    hash_object = hashlib.sha256()

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)

            if not chunk:
                break

            hash_object.update(chunk)

    return hash_object.hexdigest()


def verify_sha256(file_path, expected_hash):
    actual_hash = calculate_sha256(file_path, 65536)  # Use a reasonable chunk size

    return actual_hash == expected_hash


def main():
    if len(os.sys.argv) > 1:
        for file in os.sys.argv[1:]:
            if not os.path.isfile(file):
                continue

            print(f""Calculating and verifying hashes for {file}..."")

            try:
                md5_hash = calculate_sha256(file, 65536)
                sha256_hash = calculate_sha256(file, 65536)

                print(f""MD5 hash: {md5_hash}"")
                print(f""SHA-256 hash: {sha256_hash}"")

                if verify_sha256(file, sha256_hash):
                    print(f""{file} passes SHA-256 verification"")
                else:
                    print(f""{file} fails SHA-256 verification"")
            except Exception as e:
                print(f""Error processing {file}: {e}"")
    else:
        print(""Please provide one or more files as input arguments"")


if __name__ == ""__main__"":
    main()
