import hashlib
import secrets

def generate_password(username):
    rule_set = {
        'username_length': 8,
        'uppercase_count': 2,
        'lowercase_count': 2,
        'digit_count': 2,
        'special_char_count': 2,
        'unique_special_chars': ['!', '@', '#', '$', '%', '^', '&', '*'],

        # Key and initialization vector for DES encryption
        'des_key': hashlib.sha256(secrets.token_bytes(16)).digest(),
        'iv_value': hashlib.sha256(secrets.token_bytes(16)).digest(),

        # DES cipher modes: ECB, EDE, EDE3, CFB
        'cipher_modes': ['ecb', 'ede', 'ede3', 'cfb']
    }

    def get_random_char():
        return secrets.choice(rule_set['unique_special_chars'] + str(range(10)) + 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ')

    password_parts = []

    for _ in range(rule_set['username_length']):

        if _ < rule_set['uppercase_count']:
            password_parts.append(get_random_char().upper())
        elif _ < rule_set['uppercase_count'] + rule_set['lowercase_count']:
            password_parts.append(get_random_char().lower())
        else:
            password_parts.append(str(secrets.randbelow(10)))

    for _ in range(rule_set['special_char_count']):
        password_parts.append(get_random_char())

    random_password = ''.join(password_parts)

    # Implementing cipher modes logic
    for mode in rule_set['cipher_modes']:
        if mode == 'ecb':
            encrypted_password = hashlib.sha256(random_password.encode()).hexdigest()
        elif mode == 'ede':
            encrypted_password = hashlib.sha256(hashlib.sha256(random_password.encode()).digest()).hexdigest()
        elif mode == 'ede3':
            encrypted_password = hashlib.sha256(hashlib.sha256(hashlib.sha256(random_password.encode()).digest()).digest()).hexdigest()
        elif mode == 'cfb':
            encrypted_password = random_password

    return encrypted_password
