import random
from typing import List, Tuple

class Stock:
    def __init__(self, symbol: str):
        self.symbol = symbol
        self.price = round(random.uniform(10, 100), 2)
        self.quantity = random.randint(1, 100)

class Portfolio:
    def __init__(self):
        self.stocks: List[Stock] = []

    def add_stock(self, stock: Stock):
        self.stocks.append(stock)

    def execute_transaction(self, transaction: Tuple[str, float, int]):
        for stock in self.stocks:
            if stock.symbol == transaction[0]:
                if transaction[1] == 'buy':
                    stock.quantity += transaction[2]
                elif transaction[1] == 'sell':
                    if transaction[2] <= stock.quantity:
                        stock.quantity -= transaction[2]
                    else:
                        print(""Insufficient quantity of stock"")
                        return
        self.calculate_portfolio_value()

    def calculate_portfolio_value(self):
        total_value = 0
        for stock in self.stocks:
            total_value += stock.price * stock.quantity
        print(f""Portfolio value: {total_value:.2f}"")

def main():
    portfolio = Portfolio()
    for _ in range(10):  # Generate randomized stocks
        stock = Stock(f""STOCK{random.randint(1, 1000)}"")
        portfolio.add_stock(stock)

    transactions = [
        (""STOCK123"", ""buy"", 50),
        (""STOCK456"", ""sell"", 20),
        (""STOCK789"", ""buy"", 30),
        # Add more transactions here
    ]

    for transaction in transactions:
        portfolio.execute_transaction(transaction)

if __name__ == ""__main__"":
    main()
