import sys
from functools import lru_cache

def process_json(input_file, query):
    # Load JSON file
    with open(input_file, 'r') as f:
        data = json.load(f)

    # Parse and apply the query
    @lru_cache(maxsize=None)
    def recursive_search(data, query):
        if isinstance(query, str):  # If query is a string
            return [d for d in data if json.loads(query) == json.loads(d)]
        elif isinstance(query, dict):
            result = []
            for k, v in query.items():
                if k not in data[0]:
                    return []  # Query key does not exist in the data
                for item in data:
