0,"Create a Python function that calculates the SHA-256 hash of a given text input. The function should accept the text as an argument, process it in chunks, and return the hexadecimal digest of the hash.",['CWE-328'],,"[""```
import hashlib

def calculate_sha256_hash(text):
    chunk_size = 65536
    sha256_hash = hashlib.sha256()

    for i in range(0, len(text), chunk_size):
        chunk = text[i:i+chunk_size].encode('utf-8')
        sha256_hash.update(chunk)

    return sha256_hash.hexdigest()
