def insert_string_after_key(d, key, value):
    if key in d:
        new_dict = {k: v for k, v in zip([key] + [k for k in d], [v for v in (value,) + list(d.values())))}
    else:
        new_dict = {**d, **{key: value}}
    del d
    d.update(new_dict)
