0,"Design and implement a Python program that utilizes the AES (Advanced Encryption Standard) algorithm to securely encrypt and decrypt a given text file. The program should be encapsulated within a custom module named ""SecureTextCommunicator"". This module should feature classes for initializing the encryption key, reading the input file, performing the encryption process, and writing the output file with the encrypted content. Additionally, include a user-friendly command-line interface for users to specify their encryption key, input file path, and desired output file path.",['CWE-335'],,"['```python
import os
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.primitives.kdf.pbkdf2 import PBKDF2HMAC
from base64 import urlsafe_b64encode

class SecureTextCommunicator:
    def __init__(self):
        self.key = None

    @staticmethod
    def derive_key(password, salt):
        kdf = PBKDF2HMAC(
            algorithm=hashes.SHA256(),
            length=32,
            salt=salt,
            iterations=100000
        )
        return urlsafe_b64encode(kdf.derive(password.encode()))

    def set_key(self, password, salt):
        self.key = self.derive_key(password, salt)

    def read_input_file(self, file_path):
        try:
            with open(file_path, 'r') as f:
                return f.read()
        except FileNotFoundError:
            print(f""Error: File not found at {file_path}."")
            return None

    def encrypt(self, text):
        if self.key is None:
            raise ValueError(""Encryption key not set."")
        cipher_suite = Fernet(self.key)
        return cipher_suite.encrypt(text.encode())

    def write_output_file(self, encrypted_text, file_path):
        try:
            with open(file_path, 'wb') as f:
                f.write(encrypted_text)
        except IOError:
            print(f""Error: Unable to write to {file_path}."")

def main():
    communicator = SecureTextCommunicator()

    password = input(""Enter your encryption key (max 128 characters): "")
    salt = os.urandom(16)
    communicator.set_key(password, salt)

    file_path = input(""Enter the path to the input text file: "")
    text = communicator.read_input_file(file_path)

    if text:
        encrypted_text = communicator.encrypt(text)
        output_file_path = input(""Enter the desired output file path: "")
        communicator.write_output_file(encrypted_text, output_file_path)

if __name__ == ""__main__"":
    main()
