import random
import time
import http.client
from urllib.parse import urlparse, urlunparse

class HttpRequest:
    def __init__(self):
        self.url = f""{random.choice(['http', 'https'])}://{random.randint(1000, 9999)}.com""
        self.method = random.choice(['GET', 'POST', 'PUT', 'DELETE'])
        self.headers = {'Host': urlparse(self.url).netloc}

class Server:
    def __init__(self):
        self.inactive = True
        self.requests = []

    def execute_request(self, request):
        conn = http.client.HTTPConnection(urlparse(request.url).hostname, port=urlparse(request.url).port)
        conn.request(request.method, request.url)

        response = conn.getresponse()
        status_code = response.status

        if request.url.endswith('/'):
            request.headers['Content-Type'] = 'application/x-www-form-urlencoded'
            request.headers['Content-Length'] = str(random.randint(1000, 9999))

        print(f""Request: {request.method} {request.url} -> Status Code: {status_code}"")

    def run(self):
        while True:
            if not self.inactive and random.random() < 0.1:
                self.inactive = True
                print(""Server inactive."")
                time.sleep(random.randint(5, 15))
            elif not self.inactive and random.random() > 0.8:
                self.inactive = False
                print(""Server active."")

            if self.inactive:
                for request in self.requests[:]:
                    self.execute_request(request)
                    self.requests.remove(request)

    def add_request(self, request):
        self.requests.append(request)

# Create instances of HttpRequest and Server
requests = [HttpRequest() for _ in range(5)]
server = Server()

# Add requests to the server
for request in requests:
    server.add_request(request)

# Run the server service
server.run()
