from flask import Flask, request, jsonify
app = Flask(__name__)

# Sample data structure for resources
resources = [
    {""id"": 1, ""name"": ""Resource 1"", ""description"": ""This is Resource 1""},
    {""id"": 2, ""name"": ""Resource 2"", ""description"": ""This is Resource 2""}
]

@app.route('/create-resource', methods=['POST'])
def create_resource():
    data = request.get_json()
    new_resource = {""id"": len(resources) + 1, **data}
    resources.append(new_resource)
    return jsonify(new_resource), 201

@app.route('/update-resource/<int:resource_id>', methods=['PUT'])
def update_resource(resource_id):
    for resource in resources:
        if resource[""id""] == resource_id:
            data = request.get_json()
            resource.update(data)
            return jsonify(resource), 200
    return jsonify({""error"": ""Resource not found""}), 404

if __name__ == '__main__':
    app.run(debug=True)
