import requests
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa
from py2neo import Graph, Node, Relationship, neo4j
import random

def fetch_certificate_and_private_key(oauth_request):
    private_key_url = oauth_request['private_key_url']
    certificate_url = oauth_request['certificate_url']

    private_key_response = requests.get(private_key_url)
    certificate_response = requests.get(certificate_url)

    if private_key_response.status_code != 200 or certificate_response.status_code != 200:
        raise Exception(""Failed to fetch private key or certificate"")

    private_key_pem = serialization.load_pem_private_key(private_key_response.content, password=None)
    certificate_pem = serialization.load_pem_x509_certificate(certificate_response.content)

    return certificate_pem.public_bytes(serialization.Encoding.PEM), \
           private_key_pem.private_bytes(serialization.Encoding.PEM)

def add_random_graph_elements(graph_instance):
    existing_nodes = list(graph_instance.nodes)

    num_vertices = random.randint(15, 40)

    for _ in range(num_vertices):
        while True:
            vertex_properties = {'random_property': random.randint(1, 100)}
            vertex_label = 'RandomVertex'
            try:
                new_vertex_id = graph_instance.create_node(vertex_label, **vertex_properties).id
                break
            except neo4j.exceptions.ClientError as e:
                if 'already exists' not in str(e):
                    raise e

        existing_nodes.append(new_vertex_id)

    num_edges = random.randint(30, 75)

    for _ in range(num_edges):
        start_node_id = random.choice(existing_nodes)
        end_node_id = random.choice(existing_nodes)
        relationship_type = 'RandomRelationship'

        try:
            graph_instance.create_relationship(start_node_id, relationship_type, end_node_id)
        except neo4j.exceptions.ClientError as e:
            if 'already exists' not in str(e):
                raise e

def main():
    oauth_request = {'private_key_url': 'https://example.com/private_key', 'certificate_url': 'https://example.com/certificate'}
    graph_instance = Graph('bolt://localhost:7687', auth=('neo4j', 'password'))

    certificate_pem, private_key_pem = fetch_certificate_and_private_key(oauth_request)

    add_random_graph_elements(graph_instance)

if __name__ == '__main__':
    main()
