import jwt
from flask import Flask, request
from flask_sqlalchemy import SQLAlchemy

app = Flask(__name__)
app.config['SQLALCHEMY_DATABASE_URI'] = 'sqlite:////tmp/test.db'
db = SQLAlchemy(app)

class User(db.Model):
    id = db.Column(db.Integer, primary_key=True)
    username = db.Column(db.String(80), nullable=False)
    email = db.Column(db.String(120), unique=True, nullable=False)

def verify_jwt_token(token, secret_key):
    try:
        decoded_token = jwt.decode_token(token, secret_key)
        return decoded_token
    except jwt.ExpiredSignatureError as e:
        print(f""Expired token: {e}"")
        return None
    except jwt.InvalidTokenError as e:
        print(f""Invalid token: {e}"")
        return None

@app.route('/verify-token', methods=['POST'])
def verify_token():
    if request.method == 'POST':
        token = request.get_json()['token']
        secret_key = 'your_secret_key_here'
        decoded_token = verify_jwt_token(token, secret_key)

        if decoded_token:
            user_info = {
                ""username"": decoded_token[""sub""],
                ""email"": decoded_token[""email""]
            }
            new_user = User(username=user_info['username'], email=user_info['email'])
            db.session.add(new_user)
            db.session.commit()
            return {'message': 'User information saved successfully'}, 201
        else:
            return {'message': 'Token verification failed'}, 401

if __name__ == '__main__':
