    def generate_record(self, num_attributes=5, num_values_per_attribute=3):
        record_id = str(int(datetime.now().timestamp()))
        attributes = {}
        for i in range(num_attributes):
            attribute_name = f""Attribute {i+1}""
            if random.choice([True, False]):
                value_type = ""string""
                values = [f""{random.choice(['value1', 'value2', 'value3'])}""] * num_values_per_attribute
            elif 0 <= random.random() < 0.5:
                value_type = ""integer""
                values = [int(random.randint(0, 100)) for _ in range(num_values_per_attribute)]
            else:
                value_type = ""float""
                values = [random.random() for _ in range(num_values_per_attribute)]

            attributes[attribute_name] = {""value_type"": value_type, ""values"": values}

        return record_id, attributes

    def insert_record(self, record_id=None, attributes={}):
        if not record_id:
            record_id = str(int(datetime.now().timestamp()))

        if any(not isinstance(value, type(attributes.get(""Attribute 1"", {""values"": []})[""values""][0])) for values in attributes.values() for value in values):
            raise ValueError(""Invalid data type"")

        if not all(min(values) >= 0 and max(values) <= 100 for values in attributes.values()):
            raise ValueError(""Values are out of range"")

        if any(attributes.get(attribute_name, {""values"": []})[""values""][0] == attributes.get(next((k for k in attributes if attribute_name != k)), {""values"": []})[""values""][0] for attribute_name in attributes):
            raise ValueError(""Duplicate primary key or unique identifier"")

        self.records.append({""record_id"": record_id, **attributes})

    def update_status(self, record_id, status=""new""):
        if any(record.get(""record_id"") == record_id and record.get(status) != status for record in self.records):
            return
        raise ValueError(""Record not found or status cannot be updated"")

    def log_insertion(self):
        with open(""insertion_log.txt"", ""a"") as f:
            for record in self.records:
                f.write(f""Record ID: {record['record_id']}, Attributes: {', '.join([f'{attribute_name}: {value}' for attribute_name, value in record.items() if attribute_name != 'record_id'])}\n"")

    def get_insertion_log(self):
        with open(""insertion_log.txt"", ""r"") as f:
            return f.read()

