import os
import psycopg2
from sqlalchemy import create_engine

class DatabaseConnection:
    def __init__(self):
        self.config = {
            'PG_HOST': os.environ.get('PG_HOST'),
            'PG_USER': os.environ.get('PG_USER'),
            'PG_PASSWORD': os.environ.get('PG_PASSWORD'),
            'PG_DB': os.environ.get('PG_DB')
        }

    def establish_connection(self, db_type):
        if db_type == 'PostgreSQL':
            conn = psycopg2.connect(
                host=self.config['PG_HOST'],
                user=self.config['PG_USER'],
                password=self.config['PG_PASSWORD'],
                database=self.config['PG_DB']
            )
        elif db_type == 'SQLite':
            # implement SQLite connection
            pass
        else:
            raise ValueError('Unsupported database type')

        return conn

    def execute_query(self, conn, query):
        cursor = conn.cursor()
        try:
            cursor.execute(query)
            result = cursor.fetchall()
            return result
        except psycopg2.Error as e:
            print(f'Error executing query: {e}')
            raise

    def close_connection(self, conn):
        conn.close()

def database_factory(db_type):
    if db_type == 'PostgreSQL':
        return DatabaseConnection()
    elif db_type == 'SQLite':
        # implement SQLite connection factory
        pass
    else:
        raise ValueError('Unsupported database type')

# Example usage:
db = database_factory('PostgreSQL')
conn = db.establish_connection('PostgreSQL')
result = db.execute_query(conn, 'SELECT * FROM table_name')
db.close_connection(conn)
