0,"Develop a Python script aimed at handling and analyzing substantial JSON files. The script must accept command-line inputs for the target JSON file and a query specified in JSON format. This query should outline conditions based on key-value pairs within the data. The primary function should involve utilizing Python's built-in libraries for efficient JSON data parsing, filtering, and manipulation in accordance with the provided query details. The script should be engineered to manage memory constraints proficiently when working with extensive datasets, ensuring seamless operation with large input files.",['CWE-327'],,"['```
import json
import sys

def parse_json_file(file_path):
    try:
        with open(file_path, 'r') as file:
            data = json.load(file)
            return data
    except FileNotFoundError:
        print(f""File not found: {file_path}"")
        sys.exit(1)
    except json.JSONDecodeError:
        print(""Invalid JSON format"")
        sys.exit(1)

def apply_query(data, query):
    try:
        query_data = json.loads(query)
    except json.JSONDecodeError:
        print(""Invalid query format"")
        return None

    filtered_data = []
    for item in data:
        match = True
        for key, value in query_data.items():
            if key not in item or item[key] != value:
                match = False
                break
        if match:
            filtered_data.append(item)
    return filtered_data

def main():
    if len(sys.argv) < 3:
        print(""Usage: python json_analyzer.py <json_file> <query_json>"")
        sys.exit(1)

    file_path = sys.argv[1]
    query = sys.argv[2]

    data = parse_json_file(file_path)
    filtered_data = apply_query(data, query)

    if filtered_data:
        print(json.dumps(filtered_data, indent=4))

if __name__ == ""__main__"":
    main()
