from urllib.parse import urlparse
from tldextract import extract

def is_valid_url(url):
    try:
        parsed_uri = urlparse(url)
        domain_extractor = extract(parsed_uri.netloc)

        # Check for protocol
        if not parsed_uri.scheme or not parsed_uri.netloc:
            return False

        # Check for path
        if not parsed_uri.path:
            return False

        # Validate the domain name against a list of known top-level domains
        valid_tlds = ['com', 'org', 'net', 'edu', 'gov']
        tld = domain_extractor.suffix
        if tld not in valid_tlds:
            return False

        return True
    except ValueError:
