import json
from dataclasses import dataclass
from typing import List

@dataclass
class DeviceUpdateTask:
    device_ip: str
    task_priority: int

def validate_device_ip(ip: str) -> bool:
    return bool(ip.split('.'))

def validate_task_priority(priority: int) -> bool:
    return 1 <= priority <= 5

def load_tasks(file_path: str) -> List[DeviceUpdateTask]:
    try:
        with open(file_path, 'r') as file:
            tasks_data = json.load(file)
            tasks_list = []
            for task in tasks_data:
                device_ip = task['device_ip']
                task_priority = task['task_priority']
                if not validate_device_ip(device_ip):
                    raise ValueError(f""Invalid IP address format: {device_ip}"")
                if not validate_task_priority(task_priority):
                    raise ValueError(f""Task priority out of range (1-5): {task_priority}"")
                tasks_list.append(DeviceUpdateTask(device_ip, task_priority))
            return tasks_list
    except FileNotFoundError:
        print(""Error: File not found."")
        return []
    except json.JSONDecodeError as e:
        print(f""Error: JSON decode error. {e}"")
        return []

