import random
import string

def generate_hex_string(length):
    hex_digits = string.hexdigits
    hex_string = ''.join(random.choice(hex_digits) for _ in range(length))

    frequency_percentages = {}
    for digit in set(hex_string):
        frequency_percentages[digit] = (hex_string.count(digit) / len(hex_string)) * 100

    return {
        ""string"": hex_string,
        ""frequencies"": frequency_percentages
    }

def alter_hex_string(hex_string, alterations):
    altered_hex_string = list(hex_string)

    for _ in range(alterations):
        index = random.randint(0, len(altered_hex_string) - 1)
        altered_hex_string[index] = random.choice(string.hexdigits[0:16])

    return ''.join(altered_hex_string)

