import os
from cryptography.hazmat.primitives import serialization
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from base64 import b64encode, b64decode

class EncryptionSoftware:
    def __init__(self):
        self.keys = {}

    def generate_rsa_key(self):
        private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048,
            backend=default_backend()
        )
        public_key = private_key.public_key()
        with open(""rsa_private.pem"", ""wb"") as f:
            f.write(private_key.private_bytes(
                encoding=serialization.Encoding.PEM,
                format=serialization.PrivateFormat.Traditional,
                encryption_algorithm=serialization.NoEncryption()
            ))
        with open(""rsa_public.pem"", ""wb"") as f:
            f.write(public_key.public_bytes(
                encoding=serialization.Encoding.OpenSSH,
                format=serialization.PublicFormat.OpenSSH
            ))

    def generate_aes_key(self):
        key = os.urandom(32)
        with open(""aes_key.txt"", ""w"") as f:
            f.write(b64encode(key).decode())

    def load_rsa_keys(self):
        self.keys[""rsa_private""] = serialization.load_pem_private_key(
            open(""rsa_private.pem"", ""rb""),
            password=None,
            backend=default_backend()
        )
        self.keys[""rsa_public""] = serialization.load_ssh_public_key(
            open(""rsa_public.pem"", ""rb"")
        )

    def load_aes_key(self):
        with open(""aes_key.txt"", ""r"") as f:
            self.keys[""aes""] = b64decode(f.read())

    def encrypt_rsa(self, data):
        encrypted_data = self.keys[""rsa_private""].public_key().encrypt(
            padding.OAEP(
                mgf=padding.MGF1(algorithm=self.keys[""rsa_private""].algorithm),
                algorithm=self.keys[""rsa_private""].algorithm,
                label=None
            ).encrypt(data.encode()),
            default_backend()
        )
        return encrypted_data

    def decrypt_rsa(self, data):
        decrypted_data = self.keys[""rsa_private""].decrypt(
            padding.OAEP(
                mgf=padding.MGF1(algorithm=self.keys[""rsa_private""].algorithm),
                algorithm=self.keys[""rsa_private""].algorithm,
                label=None
            ).decrypt(data),
            default_backend()
        )
        return decrypted_data.decode()

    def encrypt_aes(self, data):
        cipher = Cipher(
            algorithms.AES(self.keys[""aes""]),
            modes.ECB(),
            backend=default_backend()
        )
        encryptor = cipher.encryptor()
        encrypted_data = encryptor.update(data.encode()) + encryptor.finalize()
        return b64encode(encrypted_data).decode()

    def decrypt_aes(self, data):
        cipher = Cipher(
            algorithms.AES(self.keys[""aes""]),
            modes.ECB(),
            backend=default_backend()
        )
        decryptor = cipher.decryptor()
        decrypted_data = decryptor.update(b64decode(data.encode())) + decryptor.finalize()
        return decrypted_data.decode()

    def run(self):
        self.generate_rsa_key()
        self.generate_aes_key()
        self.load_rsa_keys()
        self.load_aes_key()
        while True:
            choice = input(""Enter 'rsa' for RSA encryption, 'aes' for AES encryption, or 'quit' to exit: "")
            if choice == ""rsa"":
