import os
import hashlib
import base64
from cryptography.hazmat.primitives import serialization, hashes
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.padding import PKCS7
from cryptography.hazmat.primitives.asymmetric import rsa
import argparse
import logging

class SecureTextCommunicator:
    def __init__(self):
        self.logger = logging.getLogger(__name__)
        self.logger.setLevel(logging.INFO)

    def generate_key(self, key_length, strength, complexity):
        if key_length < 128:
            raise ValueError(""Key length must be at least 128 bits (16 bytes)"")
        if not isinstance(key_length, int) or not isinstance(strength, int) or not isinstance(complexity, int):
            raise TypeError(""Key length, strength, and complexity must be integers"")

        key = os.urandom(key_length // 8)
        self.logger.info(f""Generated key of {key_length} bits with strength {strength} and complexity {complexity}"")
        return base64.b64encode(key).decode('utf-8')

    def save_key(self, key_file_path, encryption_key):
        if not isinstance(encryption_key, str) or len(encryption_key) < 22:
            raise TypeError(""Encryption key must be a base64-encoded string at least 22 characters long"")

        with open(key_file_path, 'w') as f:
            f.write(encryption_key)
        self.logger.info(f""Saved encryption key to {key_file_path}"")

    def load_key(self, key_file_path):
        try:
            with open(key_file_path, 'r') as f:
                return base64.b64decode(f.read()).hex()
        except FileNotFoundError:
            raise ValueError(f""File '{key_file_path}' not found"")
        except Exception as e:
            self.logger.error(f""Error reading key file: {e}"")
            raise

    def encrypt_file(self, input_file_path, output_file_path, encryption_key):
        if not isinstance(encryption_key, str) or len(encryption_key) < 22:
            raise TypeError(""Encryption key must be a base64-encoded string at least 22 characters long"")

        with open(input_file_path, 'rb') as f_in, open(output_file_path, 'wb') as f_out:
            iv = os.urandom(16)
            cipher = Cipher(algorithms.AES( encryption_key.encode('utf-8'), backend=default_backend()), modes.CBC(iv), backend=default_backend())
            encryptor = cipher.encryptor()
            padder = PKCS7(encryption_key.encode('utf-8')).padder()
            padded_data = padder.update(f_in.read()) + padder.finalize()
            encrypted_data = encryptor.update(padded_data) + encryptor.finalize()
            f_out.write(iv + encrypted_data)

    def decrypt_file(self, input_file_path, output_file_path, encryption_key):
        if not isinstance(encryption_key, str) or len(encryption_key) < 22:
            raise TypeError(""Encryption key must be a base64-encoded string at least 22 characters long"")

        with open(input_file_path, 'rb') as f_in, open(output_file_path, 'wb') as f_out:
            iv = f_in.read(16)
            cipher = Cipher(algorithms.AES(encryption_key.encode('utf-8'), backend=default_backend()), modes.CBC(iv), backend=default_backend())
            decryptor = cipher.decryptor()
            encrypted_data = f_in.read(-1)
            decrypted_data = decryptor.update(encrypted_data) + decryptor.finalize()
            unpadder = PKCS7(encryption_key.encode('utf-8')).unpadder()
            padded_decrypted_data = decrypted_data
            while len(padded_decrypted_data) < len(decrypted_data):
                padded_decrypted_data += b'\0'
            data = unpadder.update(padded_decrypted_data) + unpadder.finalize()
            f_out.write(data)

    def main(self, key_length, strength, complexity, input_file_path, output_file_path, mode, iv_generation_method):
        if not isinstance(key_length, int) or not isinstance(strength, int) or not isinstance(complexity, int) or not isinstance(input_file_path, str) or not isinstance(output_file_path, str) or not isinstance(mode, str) or not isinstance(iv_generation_method, str):
            raise TypeError(""All input parameters must be integers for key length and strength, string for file paths, mode of operation, and IV generation method"")

        encryption_key = self.generate_key(key_length, strength, complexity)
        if mode.lower() == 'ecb':
            cipher_mode = modes.ECB
        elif mode.lower() == 'cbc':
            cipher_mode = modes.CBC
        else:
            raise ValueError(""Invalid mode of operation. Choose ECB or CBC."")

        if iv_generation_method.lower() == 'random':
            iv = os.urandom(16)
        elif iv_generation_method.lower() == 'user-provided':
            if not isinstance(iv_generation_method, str) or len(iv_generation_method) < 16:
                raise TypeError(""IV generation method must be a string at least 16 characters long"")
            iv = bytes.fromhex(iv_generation_method)
        else:
            raise ValueError(""Invalid IV generation method. Choose random or user-provided."")

        self.encrypt_file(input_file_path, output_file_path, encryption_key)

if __name__ == ""__main__"":
    parser = argparse.ArgumentParser(description='SecureTextCommunicator')
    parser.add_argument('--key_length', type=int, required=True)
    parser.add_argument('--strength', type=int, required=True)
    parser.add_argument('--complexity', type=int, required=True)
    parser.add_argument('--input_file_path', type=str, required=True)
    parser.add_argument('--output_file_path', type=str, required=True)
    parser.add_argument('--mode', type=str, required=True)
    parser.add_argument('--iv_generation_method', type=str, required=True)

    args = parser.parse_args()

    communicator = SecureTextCommunicator()
    try:
        communicator.main(args.key_length, args.strength, args.complexity, args.input_file_path, args.output_file_path, args.mode, args.iv_generation_method)
    except Exception as e:
        self.logger.error(f""An error occurred: {e}"")
