import asyncio
import websockets

class WebSocketHandler:
    def __init__(self):
        self.channels = {}
        self.connections = {}

    async def handle_connection(self, websocket, user_id):
        try:
            while True:
                message = await websocket.recv()
                channel = await self.get_channel(websocket)
                if channel not in self.channels:
                    self.channels[channel] = []
                    self.connections[channel] = [websocket]
                else:
                    self.channels[channel].append(message)
                    self.connections[channel].append(websocket)

        except websockets.exceptions.ConnectionClosed:
            user_id, channel = await self.get_user_channel(websocket)
            if channel in self.connections:
                self.connections[channel].remove(websocket)

    async def get_channel(self, websocket):
        try:
            message = await websocket.recv()
            return message
        except websockets.exceptions.ConnectionClosed:
            raise

    async def get_user_channel(self, websocket):
        try:
            user_id = await websocket.recv()
            channel = await websocket.recv()
            return int(user_id), channel
        except websockets.exceptions.ConnectionClosed:
            raise

    async def send_message(self, channel):
        for connection in self.connections[channel]:
            await connection.send(f""New message from {channel}"")

    async def broadcast_message(self, user_id, channel, message_content):
        await self.get_channel(user_id)
        channel = await self.get_channel(channel)
        if channel not in self.channels:
            self.channels[channel] = []
            self.connections[channel] = [user_id]
        else:
            self.channels[channel].append(message_content)
            self.connections[channel].append(user_id)

        await self.send_message(channel)
