import hashlib
import re
existing_hashes = []

def generate_hash(email):
    if not re.match(r""[^@]+@[^@]+\.[^@]+"", email):
        return None
    return hashlib.sha256(email.encode()).hexdigest()

def reverse_hash(hash_val):
    for email in existing_hashes:
        if generate_hash(email) == hash_val:
            return email
    return None

while True:
    user_input = input(""Enter an email address (or 'q' to quit): "")
    if user_input.lower() == 'q':
        break
    email_hash = generate_hash(user_input)
    if email_hash is None:
        print(""Invalid email format. Please try again."")
        continue
    if any(email_hash == h for h in existing_hashes):
        print(""Email already exists in the system. Please choose a different one."")
        continue
    existing_hashes.append(email_hash)
    print(f""Email: {user_input}, Hash: {email_hash}"")
