import logging
from multiprocessing import Pool
from concurrent.futures import ThreadPoolExecutor
import functools
import os
import sys
import binascii
from typing import Dict, List

class TrieNode:
    def __init__(self):
        self.children: Dict[str, 'TrieNode'] = {}
        self.path_length = 0
        self.max_palindrome_length = 0
        self.count: int = 0

class BinaryReader:
    def __init__(self, file_path: str, chunk_size: int):
        self.file_path = file_path
        self.chunk_size = chunk_size
        self.file_pointer = open(file_path, 'rb')

    def read(self) -> bytes:
        if not self.file_pointer:
            return b''

        buffer = bytearray(self.chunk_size)
        num_bytes_read = os.read(self.file_pointer.fileno(), self.chunk_size)

        if num_bytes_read == 0:
            self.file_pointer.close()
            self.file_pointer = None
            return b''

        bytes_read = memoryview(buffer)[:num_bytes_read]
        return bytes_read

def is_palindrome(s: str) -> bool:
    return s == s[::-1]

def update_trie(node: TrieNode, path: str) -> Tuple[TrieNode, int]:
    if not node.children.get(path[0]):
        node.children[path[0]] = TrieNode()
    current_node = node.children[path[0]]
    current_node.path_length += 1
    if is_palindrome(path):
        current_node.max_palindrome_length = max(current_node.max_palindrome_length, len(path))
        current_node.count += 1
    return current_node, len(path)

def parse_binary_file(file_path: str, chunk_size: int) -> List[Tuple[str, int]]:
    reader = BinaryReader(file_path, chunk_size)
    results = []
    with ThreadPoolExecutor() as executor:
        for path_length, _ in executor.map(functools.partial(update_trie, TrieNode()), [reader.read().decode('utf-8') for _ in range(chunk_size)]):
            results.append((path_length, 1))
    return results

def write_trie_to_file(trie_root: TrieNode, file_path: str) -> None:
    def recursive_write(node: TrieNode, path: str = '') -> None:
        if not node.children:
            return
        for child in node.children.values():
            recursive_write(child, path + (child.path_length > 0 and '1' or '0'))
    with open(file_path, 'w') as f:
        f.write(recursive_write(trie_root))

def main() -> None:
    if len(sys.argv) > 2 and sys.argv[2] == '--case-insensitive':
        case_sensitive = False
    else:
        case_sensitive = True

    if len(sys.argv) > 3 and sys.argv[3] == '--write-trie':
        write_trie_to_file(TrieNode(), 'trie.txt')

    logging.basicConfig(level=logging.INFO)

    with ThreadPoolExecutor() as executor:
        for _ in executor.map(parse_binary_file, [file_path], [chunk_size]):
            pass

if __name__ == ""__main__"":
    main()
