import os
from fontTools.ttLib import TTFont
import hashlib
import shutil

class FontCacheManager:
    def __init__(self, cache_dir=os.path.expanduser('~/.cache/fonts')):
        self.cache_dir = cache_dir
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)

    def load_font(self, font_path):
        return TTFont(font_path)

    def save_font(self, font, unique_id):
        file_path = os.path.join(self.cache_dir, f'{unique_id}.ttf')
        with open(file_path, 'wb') as f:
            f.write(font.getGlyphOrder())

    def get_cached_font(self, unique_id):
        file_path = os.path.join(self.cache_dir, f'{unique_id}.ttf')
        if not os.path.exists(file_path):
            return None
        font_hash = hashlib.sha256(open(file_path, 'rb').read()).hexdigest()
        if font_hash != unique_id:
            os.remove(file_path)
            return None
        return self.load_font(file_path)

    def add_font(self, font_path, unique_id=None):
        font = self.load_font(font_path)
        if not unique_id:
            file_name = font.getGlyphOrder().decode('utf-8')
            unique_id = hashlib.sha256(file_name.encode('utf-8')).hexdigest()
        self.save_font(font, unique_id)

    def clean_up_cache(self, max_age_days):
        for file in os.listdir(self.cache_dir):
            file_path = os.path.join(self.cache_dir, file)
            if os.path.getmtime(file_path) < (datetime.datetime.now() - datetime.timedelta(days=max_age_days)).timestamp():
                os.remove(file_path)
