import sqlite3
import json

def generate_sql_query(query_type):
    if query_type == 'insert':
        return ""INSERT INTO table_name (column1, column2) VALUES (?, ?)""
    elif query_type == 'update':
        return ""UPDATE table_name SET column1 = ?, column2 = ? WHERE id = ?""
    elif query_type == 'delete':
        return ""DELETE FROM table_name WHERE id = ?""

def execute_sql_query(query, query_type):
    try:
        conn = sqlite3.connect('test.db')
        c = conn.cursor()
        if query_type == 'insert':
            c.execute(query, ('value1', 'value2'))
        elif query_type == 'update':
            c.execute(query, ('new_value1', 'new_value2', 1))
        elif query_type == 'delete':
            c.execute(query, (1,))
        conn.commit()
        conn.close()
    except sqlite3.Error as e:
        print(f""An error occurred: {e}"")

def record_outcome(query_type):
    try:
        with open('outcome.txt', 'a') as file:
            if query_type == 'insert':
                file.write(""INSERT query executed successfully\n"")
            elif query_type == 'update':
                file.write(""UPDATE query executed successfully\n"")
            elif query_type == 'delete':
                file.write(""DELETE query executed successfully\n"")
    except IOError as e:
        print(f""An error occurred: {e}"")

def main():
    query_types = ['insert', 'update', 'delete']
    for query_type in query_types:
        query = generate_sql_query(query_type)
        execute_sql_query(query, query_type)
        record_outcome(query_type)

if __name__ == ""__main__"":
    main()
