from flask import Flask, request, jsonify
import sys

app = Flask(__name__)

def create_route(route_type):
    if route_type == ""get"":
        def get_handler():
            data = {""message"": ""This is a GET request""}
            return jsonify(data), 200
    elif route_type == ""post"":
        def post_handler():
            data = {""message"": ""This is a POST request""}
            return jsonify(data), 201
    else:
        print(""Invalid route type"")
        sys.exit(1)

    return globals()[f""{route_type}_handler""]


@app.route('/' + sys.argv[2], methods=[sys.argv[3]])
def main_handler():
    return create_route(sys.argv[2])()


if __name__ == ""__main__"":
    app.run(port=int(sys.argv[1]))
