class CSVProcessor:
    def __init__(self, file_path):
        self.file_path = file_path

    def read_transactions(self):
        transactions = []
        with open(self.file_path, 'r') as csvfile:
            csv_reader = csv.DictReader(csvfile)
            for row in csv_reader:
                transactions.append(row)
        return transactions

    def write_transactions(self, data):
        with open(self.file_path, 'w', newline='') as csvfile:
            fieldnames = ['date', 'amount', 'description']
            writer = csv.DictWriter(csvfile, fieldnames=fieldnames)
            writer.writeheader()
            for transaction in data:
                writer.writerow(transaction)

    def filter_transactions(self, criteria):
        filtered_transactions = []
        criteria_json = json.loads(criteria)

        for transaction in self.read_transactions():
            if all(transaction[field] == criteria_json[field] or (isinstance(transaction[field], str) and transaction[field].lower() == criteria_json[field].lower()) for field in criteria_json.keys()):
                filtered_transactions.append(transaction)

        return filtered_transactions


