import hashlib
import os

def calculate_sha256(file_path, chunk_size):
    hash_object = hashlib.sha256()
    with open(file_path, 'rb') as file:
        while True:
            data = file.read(chunk_size)
            if not data:
                break
            hash_object.update(data)
    return hash_object.hexdigest()

def verify_sha256(file_path, expected_hash):
    actual_hash = calculate_sha256(file_path, 65536) # Using default chunk size
    return actual_hash == expected_hash

def main():
    import sys

    if len(sys.argv) < 3:
        print(""Usage: python script.py [file1] [file2] ..."")
        return

    for file in sys.argv[1:]:
        if not os.path.isfile(file):
            print(f""{file} is not a valid file."")
            continue

        sha256_hash = calculate_sha256(file, 65536) # Using default chunk size
        md5_hash = hashlib.md5(open(file, 'rb').read()).hexdigest()

        print(f""SHA-256 hash for {file}: {sha256_hash}"")
        if verify_sha256(file, sha256_hash):
            print(f""{file} has a valid SHA-256 hash."")
        else:
            print(f""{file} has an invalid SHA-256 hash."")

if __name__ == ""__main__"":
    main()
