def validate_filename(filename):
    if not re.match(r""^[a-zA-Z0-9_.-]+$"", filename):
        raise ValueError(""Invalid filename"")

def choose_file_type():
    file_types = [""txt"", ""pdf"", ""docx""]
    return input(f""Choose a file type ({', '.join(file_types)}): "")

def add_extension(filename, prefix, file_type):
    if not filename.endswith(("".jpg"", "".png"", "".jpeg"")):
        raise ValueError(""Invalid image file"")
    return f""{prefix}-{os.path.splitext(filename)[0]}.{file_type}""

def process_filename(image_stream, prefix=""""):
    try:
        validate_filename(image_stream.filename)
    except ValueError as e:
        print(f""Error: {e}"")
        new_filename = input(""Enter a valid filename with extension: "")
        image_stream.filename = new_filename

    file_type = choose_file_type()
    if not os.path.splitext(image_stream.filename)[1].lower() in [f"".{t}"" for t in file_types]:
        image_stream.filename = add_extension(image_stream.filename, prefix, file_type)

    # real-time effects and processing logic here
    print(f""Processed filename: {image_stream.filename}"")
