def generate_custom_sensor_data(m, mean, std_dev, error_prob):
    sensor_data_list = []

    for _ in range(m):
        sensor_data = CustomSensorData()

        sensor_data.SensorID = str(random.randint(1, 1000000))
        sensor_data.timestamp = datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")

        sensor_data.sensor_reading = round(random.normalvariate(mean, std_dev), 2)

        if random.random() < error_prob:
