def validate_url(url):
    try:
        parsed_url = urlparse(url)
        if not parsed_url.scheme or not parsed_url.netloc:
            return {""status"": ""Invalid"", ""message"": ""URL must have protocol and domain""}
        if parsed_url.scheme == 'https':
            # Check HTTPS connection
            if not re.match('^[a-zA-Z0-9.-]+$', parsed_url.netloc):
                return {""status"": ""Invalid"", ""message"": ""Domain name contains invalid characters""}
            if not re.match('^[a-zA-Z0-9._~%-]+$', parsed_url.path):
                return {""status"": ""Invalid"", ""message"": ""Path contains invalid characters""}
        else:
            # Check HTTP connection
            if not re.match('^[a-zA-Z0-9.-]+$', parsed_url.netloc):
                return {""status"": ""Invalid"", ""message"": ""Domain name contains invalid characters""}
            if not re.match('^[a-zA-Z0-9._~%-]+$', parsed_url.path):
                return {""status"": ""Invalid"", ""message"": ""Path contains invalid characters""}
    except ValueError:
        return {""status"": ""Invalid"", ""message"": ""URL is malformed""}

    # Check cache for existing validation result
    if url in cache:
        return cache[url]

    # Perform WHOIS lookup and store in database
    cursor.execute(""INSERT OR IGNORE INTO urls (url) VALUES (?)"", (url,))
    db_conn.commit()
    try:
        whois_info = get_whois_info(url)
        if whois_info:
            cache[url] = {""status"": ""Valid"", ""message"": f""URL {url} is valid""}
            return cache[url]
        else:
            return {""status"": ""Invalid"", ""message"": f""URL {url} is not valid""}
    except Exception as e:
        logging.error(f""Error validating URL {url}: {str(e)}"")
        return {""status"": ""Invalid"", ""message"": f""Error occurred while validating URL {url}""}

def shorten_url(url):
    # Generate unique short URL
    short_url = generate_short_url()
    # Store mapping in database
    cursor.execute(""INSERT OR IGNORE INTO urls (long_url, short_url) VALUES (?, ?)"", (url, short_url))
    db_conn.commit()
    return short_url

@app.route('/validate', methods=['POST'])
def validate_urls():
    data = request.get_json()
    results = []
    for url in data:
        result = validate_url(url)
        results.append(result)
    return jsonify(results)

@app.route('/shorten', methods=['POST'])
def shorten_urls():
    data = request.get_json()
    short_urls = []
    for url in data:
        short_url = shorten_url(url)
        short_urls.append(short_url)
    return jsonify(short_urls)

if __name__ == '__main__':
