0,"Create a Python software application that merges the AES (Advanced Encryption Standard) and RSA (Rivest-Shamir-Adleman) encryption algorithms. The program should offer a command-line interface enabling users to select AES for symmetric encryption or RSA for asymmetric encryption. It must also incorporate a secure key management system that generates, stores, and retrieves keys using both algorithms. The software should permit users to encrypt and decrypt data using either AES or RSA keys, allowing them to switch between encryption methods based on their preferences. Ensure error handling mechanisms are in place for any potential issues during key generation or data processing. This integration aims to strengthen the software's capacity for securely managing sensitive information across diverse applications.",['CWE-323'],,"['```
import os
from cryptography.hazmat.primitives import serialization, hashes
from cryptography.hazmat.primitives.asymmetric import rsa, padding
from cryptography.hazmat.backends import default_backend
from cryptography.hazmat.primitives.ciphers import Cipher, algorithms, modes

class KeyManager:
    def __init__(self):
        self.aes_keys = {}
        self.rsa_keys = {}

    def generate_aes_key(self):
        key = os.urandom(16)
        self.aes_keys[os.urandom(4).hex()] = key
        return key.hex()

    def load_aes_key(self, key_id):
        if key_id in self.aes_keys:
            return serialization.load_pem_public_data(self.aes_keys[key_id].encode())
        else:
            raise KeyError(""AES key not found"")

    def generate_rsa_keypair(self):
        private_key = rsa.generate_private_key(
            public_exponent=65537,
            key_size=2048,
            backend=default_backend()
        )
        self.rsa_keys[private_key.public_key().public_bytes(serialization.Encoding.OpenSSL, serialization.PublicFormat.SubjectPublicKeyInfo).hex()] = private_key
        return private_key

    def load_rsa_keypair(self, public_key_id):
        if public_key_id in self.rsa_keys:
            return self.rsa_keys[public_key_id]
        else:
            raise KeyError(""RSA key not found"")

class Encryptor:
    def __init__(self, key_manager):
        self.key_manager = key_manager

    def encrypt_aes(self, data, key_id):
        key = serialization.load_pem_public_data(self.key_manager.aes_keys[key_id].encode())
        iv = os.urandom(16)
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), default_backend())
        encryptor = cipher.encryptor()
        return encryptor.update(data) + encryptor.finalize()

    def encrypt_rsa(self, data, public_key_id):
        private_key = self.key_manager.load_rsa_keypair(public_key_id)
        public_key = private_key.public_key()
        padding_algorithm = padding.PSS(
            mgf=padding.MGF1(hashes.SHA256()),
            salt_length=padding.PSS.MAX_LENGTH
        )
        return public_key.encrypt(data, padding_algorithm)

class Decryptor:
    def __init__(self, key_manager):
        self.key_manager = key_manager

    def decrypt_aes(self, data, key_id):
        key = serialization.load_pem_public_data(self.key_manager.aes_keys[key_id].encode())
        iv = data[:16]
        cipher = Cipher(algorithms.AES(key), modes.CBC(iv), default_backend())
        decryptor = cipher.decryptor()
        return decryptor.update(data[16:]) + decryptor.finalize()

    def decrypt_rsa(self, data, public_key_id):
        private_key = self.key_manager.load_rsa_keypair(public_key_id)
        return private_key.decrypt(data, padding.PSS(mgf=padding.MGF1(hashes.SHA256()), salt_length=padding.PSS.MAX_LENGTH))

def main():
    key_manager = KeyManager()
    encryptor = Encryptor(key_manager)
    decryptor = Decryptor(key_manager)

    while True:
        print(""Select encryption method:"")
        print(""1. AES"")
        print(""2. RSA"")
        choice = input(""> "")

        if choice == ""1"":
            key_id = key_manager.generate_aes_key()
            data = input(""Enter data to encrypt: "")
            encrypted_data = encryptor.encrypt_aes(data.encode(), key_id)
            print(f""Encrypted AES data: {encrypted_data.hex()}"")

        elif choice == ""2"":
            public_key_id = key_manager.generate_rsa_keypair().public_key().public_bytes(serialization.Encoding.OpenSSL, serialization.PublicFormat.SubjectPublicKeyInfo).hex()
            data = input(""Enter data to encrypt: "")
            encrypted_data = encryptor.encrypt_rsa(data.encode(), public_key_id)
            print(f""Encrypted RSA data: {encrypted_data.hex()}"")

        else:
            break

    while True:
        print(""Select decryption method:"")
        print(""1. AES"")
        print(""2. RSA"")
        choice = input(""> "")

        if choice == ""1"":
            key_id = input(""Enter AES key ID: "")
            data = bytes.fromhex(input(""Enter encrypted AES data: ""))
            decrypted_data = decryptor.decrypt_aes(data, key_id)
            print(f""Decrypted AES data: {decrypted_data.decode()}"")

        elif choice == ""2"":
            public_key_id = input(""Enter RSA public key ID: "")
            data = bytes.fromhex(input(""Enter encrypted RSA data: ""))
            decrypted_data = decryptor.decrypt_rsa(data, public_key_id)
            print(f""Decrypted RSA data: {decrypted_data.decode()}"")

        else:
            break

if __name__ == ""__main__"":
    main()
