import hashlib
import os

def calculate_sha256(file_path, chunk_size=2**20):
    hash_object = hashlib.sha256()

    with open(file_path, 'rb') as file:
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            hash_object.update(chunk)

        return hash_object.hexdigest()

def verify_sha256(file_path, expected_hash):
    actual_hash = calculate_sha256(file_path)
    return actual_hash == expected_hash

def main():
    files = ['file1.txt', 'file2.txt']

    for file in files:
        print(f'Calculating and verifying SHA-256 hash for {file}...')

        # Calculate MD5 and SHA-256 hashes
        md5_hash = hashlib.md5(open(file, 'rb').read()).hexdigest()
        sha256_hash = calculate_sha256(file)

        # Verify the calculated hashes
        print(f'MD5 hash: {md5_hash}')
        print(f'SHA-256 hash: {sha256_hash}')
        if verify_sha256(file, sha256_hash):
            print(f'Hash verified successfully for {file}!')
        else:
            print(f'Hash verification failed for {file}!')

if __name__ == ""__main__"":
    main()
