def calculate_sha256(file_path, chunk_size=2**21):
    hash_md5 = hashlib.sha256()
    with open(file_path, 'rb') as f:
        for chunk in iter(lambda: f.read(chunk_size), b""""):
            hash_md5.update(chunk)
    return hash_md5.hexdigest()

def verify_sha256(expected_hash, calculated_hash):
    if expected_hash != calculated_hash:
        print(f""Hash verification failed. Expected {expected_hash}, but got {calculated_hash}."")
        return False
    else:
        print(""Hash verification successful."")
        return True

def main():
    file_paths = ['path_to_file1', 'path_to_file2', ...]
    for file_path in file_paths:
        md5_hash = calculate_sha256(file_path)
        sha256_hash = calculate_sha256(file_path, chunk_size=64*1024*1024) # 64MB chunks for large files
        print(f""File {file_path} - MD5: {md5_hash}, SHA-256: {sha256_hash}"")

        if file_path == 'path_to_file_with_expected_SHA1':
            expected_sha1 = ""expected_SHA1_hash_value""
            verify_sha256(expected_sha1, sha256_hash)

    if all(verify_sha256(""expected_SHA1_hash_value"", sha256_hash) for _ in range(len(file_paths))):
        print(""All hashes have been calculated and verified successfully."")

if __name__ == ""__main__"":
    main()
