import os
import re
import shutil
from concurrent.futures import ThreadPoolExecutor

def generate_unique_directory_name(base_name, dir_path, max_suffix=100):
    counter = 1
    while True:
        new_dir_name = f""{base_name}_{counter}""
        new_dir_path = os.path.join(dir_path, new_dir_name)

        try:
            os.makedirs(new_dir_path)
            return new_dir_path
        except FileExistsError:
            counter += 1

        if counter > max_suffix:
            print(""Error: Maximum suffix limit reached."")
            exit(1)

def create_backup_directory(directory_path):
    backup_directory = os.path.join(directory_path, ""backup"")
    os.makedirs(backup_directory)
    return backup_directory

def process_directory(dir_path, prefix=None, suffix=None):
    base_name = os.path.basename(dir_path)

    try:
        if prefix and suffix:
            full_new_dir_name = f""{prefix}_{base_name}_{suffix}""
        elif prefix:
            full_new_dir_name = f""{prefix}_{base_name}""
        elif suffix:
            full_new_dir_name = f""{base_name}_{suffix}""
        else:
            full_new_dir_name = base_name

        new_dir_path = os.path.join(dir_path, full_new_dir_name)

        # Create backup directory within new directory
        backup_directory = create_backup_directory(new_dir_path)

        print(f""Created directories: {new_dir_path}, {backup_directory}"")

    except Exception as e:
        print(f""Error processing {dir_path}: {str(e)}"")

def main():
    import argparse

    parser = argparse.ArgumentParser(description=""Create unique subdirectories in a given path."")
    parser.add_argument(""directory"", help=""Path of the root directory"")
    parser.add_argument(""-p"", ""--prefix"", help=""Prefix for generated directory names"")
    parser.add_argument(""-s"", ""--suffix"", help=""Suffix for generated directory names"")

    args = parser.parse_args()

    root_dir = args.directory.rstrip(os.sep)

    if not os.path.exists(root_dir):
        print(f""The directory '{root_dir}' does not exist."")
        exit(1)

    try:
        pool = ThreadPoolExecutor()

        for dir_path, dirs, _ in os.walk(root_dir):
            for d in dirs:
                process_directory(dir_path, prefix=args.prefix, suffix=args.suffix if args.suffix else None)

    except Exception as e:
        print(f""Error: {str(e)}"")

    finally:
        pool.shutdown()
