def fibonacci(n):
    fib_sequence = [0, 1]
    while fib_sequence[-1] <= n:
        fib_sequence.append(fib_sequence[-1] + fib_sequence[-2])
    return fib_sequence

def display_fibonacci(n, option):
    if option == ""even"":
        print([num for num in fibonacci(n) if num % 2 == 0])
    elif option == ""both"":
        print(fibonacci(n))
    else:
        print(""Invalid option. Please choose 'even' or 'both'."")

