import random
import time
import http.client
import threading

class HttpRequest:
    def __init__(self):
        self.url = f""https://example.com/{random.randint(1, 100)}""
        self.status_code = random.randint(200, 500)

class ServerService:
    def __init__(self):
        self.requests = []

    def start(self):
        threading.Thread(target=self.dispatch_requests).start()

    def dispatch_requests(self):
        while True:
            if not self.requests:
                time.sleep(random.uniform(1, 5))
                continue
            request = self.requests.pop()
            conn = http.client.HTTPSConnection('www.example.com')
            conn.request(""GET"", request.url)
            response = conn.getresponse()
            print(f""Request {request.url} returned with status code {response.status}"")
            conn.close()

    def add_request(self, request):
        self.requests.append(request)

def main():
    service = ServerService()
    for _ in range(10):
        request = HttpRequest()
        service.add_request(request)
        time.sleep(random.uniform(1, 3))

if __name__ == ""__main__"":
    main()
