import random
import time
from threading import Thread, Lock
from datetime import datetime

class Department:
    def __init__(self, name):
        self.name = name

class Employee:
    id_count = 0

    def __init__(self, department=None):
        self.EmployeeID = f""EMP-{Employee.id_count}""
        Employee.id_count += 1
        self.HireDate = datetime.now()
        self.Department = random.choice([department]) if department else None

class BackgroundProcess(Thread):
    lock = Lock()

    def __init__(self, employees):
        super().__init__()
        self.employees = employees
        self.status_updates = []

    def run(self):
        while True:
            time.sleep(random.randint(1, 10))
            with self.lock:
                for employee in self.employees:
                    if not any(entry['EmployeeID'] == employee.EmployeeID for entry in self.status_updates):
                        self.status_updates.append({
                            'EmployeeID': employee.EmployeeID,
                            'Department': employee.Department.name,
                            'StatusUpdateDate': datetime.now()
                        })
            time.sleep(random.randint(1, 5))

def main():
    departments = [Department(""Sales""), Department(""Marketing""), Department(""IT"")]
    employees = []
    for _ in range(10):
        employee = Employee(random.choice(departments))
        employees.append(employee)

    background_process = BackgroundProcess(employees)
    background_process.start()

    while True:
        input(""Press Enter to stop the application..."")

    background_process.do_stop()
    background_process.join()

if __name__ == ""__main__"":
    main()
