import json
import logging
import csv

def parse_json_data(json_file_path, output_format='plain_text'):
    try:
        with open(json_file_path, 'r') as f:
            json_data = json.load(f)

        if output_format == 'csv':
            header_keys = ['key1', 'key2', 'key3']  # predefined keys
            with open('output.csv', 'w', newline='') as csvfile:
                writer = csv.writer(csvfile)
                writer.writerow(header_keys)  # write header
                for item in json_data:
                    writer.writerow([item[key] for key in header_keys])
        elif output_format == 'plain_text':
            for item in json_data:
                print(json.dumps(item, indent=4))
        else:
            logging.error('Invalid output format. Supported formats: csv, plain_text')

    except FileNotFoundError:
        logging.error(f'File not found: {json_file_path}')
    except json.JSONDecodeError as e:
        logging.error(f'JSON decoding error: {e}')
    except Exception as e:
        logging.error(f'Unexpected error: {e}')

