class FontCacheManager:
    def __init__(self, cache_dir):
        self.cache_dir = cache_dir
        self.font_cache = {}

    def initialize_cache_directory(self):
        if not os.path.exists(self.cache_dir):
            os.makedirs(self.cache_dir)

    def load_font_into_memory(self, font_file_path):
        try:
            from fontTools.ttLib import TTFont

            with open(font_file_path, 'rb') as file:
                font_data = file.read()
            return TTFont(font_data)
        except Exception as e:
            print(f""Error loading font: {e}"")
            return None

    def save_font_to_cache(self, font_id, loaded_font):
        cache_file_path = f""{self.cache_dir}/{font_id}.ttf""
        with open(cache_file_path, 'wb') as file:
            file.write(loaded_font.getBuffer())
        self.font_cache[font_id] = cache_file_path

    def retrieve_cached_font_by_id(self, font_id):
        if font_id in self.font_cache:
            return self.load_font_into_memory(self.font_cache[font_id])
        else:
            print(f""Font with ID '{font_id}' not found in the cache."")
            return None

    def add_font_to_cache(self, font_file_path):
        loaded_font = self.load_font_into_memory(font_file_path)
        if loaded_font:
            font_id = str(hashlib.sha256(loaded_font.getBuffer()).hexdigest())
            self.save_font_to_cache(font_id, loaded_font)
