from datetime import datetime

class StackManager:
    def __init__(self):
        self.lock = threading.Lock()
        self.stacks = []

    def push(self, stack_id, element):
        with self.lock:
            self.stacks[stack_id].append(element)

    def pop(self, stack_id):
        with self.lock:
            return self.stacks[stack_id].pop()

    def log_operation(self, operation, stack_id, timestamp):
        with open(""log.txt"", ""a"") as f:
            f.write(f""{timestamp} - {operation} on Stack {stack_id}\n"")
