import re

def create_user_profile(num_profiles):
    profile_list = []
    for _ in range(num_profiles):
        username = f""usr{random.randint(1000, 9999)}""
        while any(username == p['username'] for p in profile_list):
            username = f""usr{random.randint(1000, 9999)}""

        birth_year = random.randint(1923, 2013)
        birth_month = random.randint(1, 12)
        birth_day = random.randint(1, 28 if birth_month in [1, 3, 5, 7, 8, 10, 12] else 31)

        date_of_birth = f""{birth_year}-{str(birth_month).zfill(2)}-{str(birth_day).zfill(2)}""

        gender = random.choice([""Male"", ""Female""])
        male_female_probability = [0.5, 0.45, 0.05]
        if random.random() < sum(male_female_probability):
            gender = ""Male""
        else:
            if random.random() < male_female_probability[1]:
                gender = ""Female""

        email_regex = re.compile(r'^[a-zA-Z0-9]+@example\.com$')
        while True:
            username_part = f""{username}{random.randint(100, 999)}""
            email = f""{username_part}@example.com""
            if email_regex.match(email):
                break

        profile = {
            ""username"": username,
            ""date_of_birth"": date_of_birth,
            ""gender"": gender,
            ""email"": email
        }
        profile_list.append(profile)
    return profile_list']",4,[0],[],True,0,0,0,

