import pandas as pd
from sklearn.feature_extraction.text import TfidfVectorizer
from sklearn.naive_bayes import MultinomialNB
from sklearn.model_selection import train_test_split
from sklearn.metrics import accuracy_score, classification_report
import re

class TextAnalyzer:
    def __init__(self):
        self.tfidf_vectorizer = TfidfVectorizer()

    def extract_features(self, text):
        try:
            text = str(text)
            if not text.strip():
                raise ValueError(""Empty or non-text content provided"")

            features = self.tfidf_vectorizer.fit_transform([text])
            return features.toarray()[0]
        except Exception as e:
            print(f""Error: {e}"")

    def get_keywords(self, features):
        keywords = [word for word, score in zip(self.tfidf_vectorizer.get_feature_names_out(), features) if score > 0.1]
        return keywords


class DocumentCategorizer:
    def __init__(self):
        self.classifier = MultinomialNB()

    def load_dataset(self, filepath):
        try:
            data = pd.read_csv(filepath)
            X_train, X_test, y_train, y_test = train_test_split(data['text'], data['category'], test_size=0.2)
            self.vectorizer = TfidfVectorizer()
            X_train_vec = self.vectorizer.fit_transform(X_train)
            X_test_vec = self.vectorizer.transform(X_test)

            self.classifier.fit(X_train_vec, y_train)

            y_pred = self.classifier.predict(X_test_vec)

            print(""Accuracy:"", accuracy_score(y_test, y_pred))
            print(""Classification Report:\n"", classification_report(y_test, y_pred))

        except FileNotFoundError:
            print(""File not found."")
        except Exception as e:
            print(f""Error: {e}"")

    def classify_document(self, document):
        try:
            document_vec = self.vectorizer.transform([document])

            category_proba = self.classifier.predict_proba(document_vec)[0]

            category_with_highest_proba = max(zip(category_proba, range(len(category_proba))), key=lambda x: x[0])

            return category_with_highest_proba[1], category_with_highest_proba[0]

        except Exception as e:
            print(f""Error: {e}"")


def main():
    analyzer = TextAnalyzer()
    categorizer = DocumentCategorizer()

    while True:
        choice = input(""Enter 'classify' to classify a document or 'quit' to exit: "")
        if choice.lower() == 'classify':
            document = input(""Enter the text of the document: "")
            category, probability = categorizer.classify_document(document)
            print(f""The document is classified as {category} with a probability of {probability:.2f}."")
        elif choice.lower() == 'quit':
            break
        else:
            print(""Invalid choice. Please try again."")
