        cursor = db_conn.cursor()
        query = ""INSERT OR REPLACE INTO products (name, price) VALUES (?, ?)""
        cursor.execute(query, (product_name, product_price))
        db_conn.commit()

        return ""Product inserted successfully""
    except sqlite3.Error as e:
