import base64
import datetime
from cryptography.fernet import Fernet
from cryptography.hazmat.primitives import hashes
from cryptography.hazmat.backends import default_backend

class OTPGenerator:
    def __init__(self):
        self.secret_key = Fernet.generate_key()
        self.db = {}

    def generate_otp(self, account_number, language_setting):
        timestamp = datetime.datetime.now().strftime(""%Y-%m-%d %H:%M:%S"")
        otp = f""{account_number}:{language_setting}:{timestamp}"".encode(""utf-8"")
        encoded_otp = base64.b64encode(otp)
        return encoded_otp.decode(""utf-8"")

    def validate_otp(self, otp, secret_key):
        decoded_otp = base64.b64decode(otp.encode(""utf-8""))
        expected_otp = f""{account_number}:{language_setting}:{timestamp}"".encode(""utf-8"")
        if decoded_otp == expected_otp:
            return True
        else:
            return False

    def store_otp(self, otp):
        encrypted_db_key = Fernet(self.secret_key).encrypt(otp.encode(""utf-8""))
        self.db[encrypted_db_key] = otp

    def retrieve_otp(self, encrypted_db_key):
        decrypted_otp = Fernet(self.secret_key).decrypt(encrypted_db_key)
        return decrypted_otp.decode(""utf-8"")

# Example usage:
generator = OTPGenerator()
account_number = ""12345""
language_setting = ""en-US""
otp = generator.generate_otp(account_number, language_setting)
print(f""Generated OTP: {otp}"")

validated = generator.validate_otp(otp, generator.secret_key)
if validated:
    print(""OTP is valid"")
else:
    print(""OTP is invalid"")

generator.store_otp(otp)

retrieved_otp = generator.retrieve_otp(list(self.db.keys())[0])
print(f""Retrieved OTP: {retrieved_otp}"")
