from huffman import HuffmanCoding
from uuid import UUID

class BLE_Huffman_Encode:
    def __init__(self):
        self.huffman = HuffmanCoding()

    def generate_ble_advertisement(self, input_string):
        if not isinstance(input_string, str):
            raise ValueError(""Input must be a string"")

        encoded_data = self.huffman.encode(input_string)
        service_uuid = UUID(int=0x1812).hex
        local_identifier = 0x0001

        ble_advertisement = {
            'service_uuid': service_uuid,
            'local_identifier': local_identifier,
            'manufacturer_specific_data': encoded_data.encode('utf-8'),
            'transmission_power_level': int((255 * (0.5 + (random.random() / 2))))
        }

        return ble_advertisement

    def save_ble_advertisement(self, advertisement):
        with open('advertisement.bin', 'wb') as f:
            pickle.dump(advertisement, f)

    def load_ble_advertisement(self):
        try:
            with open('advertisement.bin', 'rb') as f:
                return pickle.load(f)
        except FileNotFoundError:
            return None

    def main(self):
        input_string = ""Hello, World!""
        ble_advertisement = self.generate_ble_advertisement(input_string)
        print(""BLE Advertisement:"", ble_advertisement)

        self.save_ble_advertisement(ble_advertisement)

        loaded_advertisement = self.load_ble_advertisement()
        if loaded_advertisement:
            print(""Loaded BLE Advertisement:"", loaded_advertisement)
        else:
            print(""No BLE Advertisement found."")

if __name__ == ""__main__"":
    ble_encoder = BLE_Huffman_Encode()
    ble_encoder.main()
