class SimulatedServerService:
    def __init__(self):
        self.requests_queue = []

    def start_service(self):
        while True:
            if not self.requests_queue:
                request = self.get_request_from_queue()
                if request:
                    Thread(target=self.send_request, args=(request,)).start()
            else:
                Timer(1.0, self.start_service).start()

    def send_request(self, request):
        conn = http.client.HTTPConnection(""www.example.com"")
        headers = {}
        for key, value in request.headers.items():
            headers[key] = value
        conn.request(request.method, request.url, headers=headers)
        response = conn.getresponse()
        print(f""Request {request.url} with method {request.method} and headers {headers} received a status code of {response.status}"")

    def get_request_from_queue(self):
        if self.requests_queue:
            return self.requests_queue.pop(0)

def generate_requests(num_requests):
